import {linesFromItems,parsePages,keys,upper,exportCsv,exportTxt} from './parser.mjs?v=3';
import {verticalGridLines} from './pdf-grid.mjs?v=3';
const $=id=>document.getElementById(id);let file=null,rows=[],busy=false;
function fail(message){$('error').textContent=message;$('error').hidden=false;}
function clearError(){$('error').hidden=true;$('error').textContent='';}
function selectFile(f){if(busy)return;clearError();if(!f||!f.name.toLowerCase().endsWith('.pdf')){fail('Lütfen PDF formatında bir dosya seç.');return}if(f.size>20*1024*1024){fail('Dosya 20 MB sınırını aşıyor. PDF’yi daha küçük parçalara ayırıp tekrar dene.');return}file=f;rows=[];$('filename').textContent=f.name;$('process').disabled=false;$('result').hidden=true;$('empty').hidden=false;$('count').textContent='0 KAYIT';$('status').textContent='';$('confirmed').checked=false;$('height').value='';}
$('file').onchange=e=>selectFile(e.target.files[0]);
for(const type of ['dragenter','dragover'])$('drop').addEventListener(type,e=>{e.preventDefault();if(!busy)$('drop').classList.add('drag')});
$('drop').ondragleave=()=>$('drop').classList.remove('drag');$('drop').ondrop=e=>{e.preventDefault();$('drop').classList.remove('drag');selectFile(e.dataTransfer.files[0])};
function setBusy(value){busy=value;for(const id of ['process','file'])$(id).disabled=value;$('process').textContent=value?'Okunuyor…':'PDF’yi işle';}
function updateDownloads(){const n=rows.filter(r=>r.selected).length;$('count').textContent=n+' / '+rows.length+' KAYIT';$('csv').disabled=$('txt').disabled=!n||!$('confirmed').checked;$('all').checked=n===rows.length&&n>0;$('all').indeterminate=n>0&&n<rows.length;}
function renderRows(){const frag=document.createDocumentFragment();rows.forEach((row,i)=>{const tr=document.createElement('tr'),td=document.createElement('td'),check=document.createElement('input');check.type='checkbox';check.checked=row.selected;check.setAttribute('aria-label',`${i+1}. satırı dahil et`);check.onchange=()=>{row.selected=check.checked;$('confirmed').checked=false;updateDownloads()};td.append(check);tr.append(td);keys.forEach((key,index)=>{const cell=document.createElement('td'),input=document.createElement('input');input.value=row[key];input.setAttribute('aria-label',`${i+1}. satır ${['binici','kulüp','atın adı','yükseklik'][index]}`);input.oninput=()=>{row[key]=input.value;$('confirmed').checked=false;updateDownloads()};input.onblur=()=>{row[key]=upper(input.value);input.value=row[key]};cell.append(input);tr.append(cell)});frag.append(tr)});$('rows').replaceChildren(frag);updateDownloads();}
function showResult(data,notice){rows=data.map(r=>({...r,selected:true}));$('confirmed').checked=false;$('empty').hidden=true;$('result').hidden=false;$('notice').textContent=notice;renderRows()}
async function readLocal(){const pdfjs=await import('https://cdn.jsdelivr.net/npm/pdfjs-dist@5.4.149/build/pdf.mjs');const vendor='https://cdn.jsdelivr.net/npm/pdfjs-dist@5.4.149/';pdfjs.GlobalWorkerOptions.workerSrc=vendor+'build/pdf.worker.mjs';const task=pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),cMapUrl:vendor+'cmaps/',cMapPacked:true,standardFontDataUrl:vendor+'standard_fonts/',wasmUrl:vendor+'wasm/',isEvalSupported:false});let doc;
 try{doc=await task.promise;if(doc.numPages>300)throw Error('Bu PDF 300 sayfadan uzun. Daha küçük parçalara ayırarak tekrar dene.');const pages=[];for(let n=1;n<=doc.numPages;n++){$('status').textContent=`Sayfa ${n} / ${doc.numPages} okunuyor…`;const p=await doc.getPage(n),content=await p.getTextContent();pages.push({number:n,width:p.getViewport({scale:1}).width,lines:linesFromItems(content.items),verticals:verticalGridLines(await p.getOperatorList(),pdfjs.OPS)});p.cleanup()}
 if(!pages.some(p=>p.lines.length))throw Error('PDF’de okunabilir metin bulunamadı. Taranmış bir belge olabilir. Metni seçilebilen bir PDF yükle.');
 const data=parsePages(pages);showResult(data.rows,data.rows.length?`Taslak olarak ${data.rows.length} satır bulundu.${data.gridPages.length ? " Tablonun sütun sınırları tanındı." : ""} İsimleri, yükseklikleri ve kayıt sayısını PDF ile karşılaştır.`+(data.incomplete.length?` Eksik alan içeren satırlar: ${data.incomplete.join(", ")}.`:"")+(data.unmapped.length?` Kayıt çıkarılamayan sayfalar: ${data.unmapped.join(', ')}.`:''):'Sütun başlıkları otomatik eşleştirilemedi. PDF’yi kontrol ederek satırları elle ekleyebilirsin.');
 }finally{await task.destroy()}}
$('process').onclick=async()=>{if(!file||busy)return;clearError();setBusy(true);$('result').hidden=true;$('empty').hidden=false;rows=[];$('count').textContent='0 KAYIT';try{await readLocal();$('status').textContent='Okuma tamamlandı. Listeyi kontrol edebilirsin.'}catch(e){$('status').textContent='';fail(e.name==='PasswordException'?'PDF parola korumalı. Parolasız bir kopyasını yükle.':e.message||'PDF okunamadı. Dosyanın geçerli olduğundan emin ol.')}finally{setBusy(false)}};
$('add').onclick=()=>{rows.push({binici:'',kulup:'',atinAdi:'',yukseklik:upper($('height').value),selected:true});$('confirmed').checked=false;renderRows();$('rows').lastChild?.querySelector('input:not([type=checkbox])')?.focus()};$('apply').onclick=()=>{const h=upper($('height').value);if(!h)return;rows.forEach(r=>{if(!r.yukseklik.trim())r.yukseklik=h});$('confirmed').checked=false;renderRows()};$('all').onchange=()=>{rows.forEach(r=>r.selected=$('all').checked);$('confirmed').checked=false;renderRows()};$('confirmed').onchange=updateDownloads;
function download(format){if(!$('confirmed').checked)return;const data=rows.filter(r=>r.selected);if(!data.length)return;const content=format==='csv'?exportCsv(data):exportTxt(data);const blob=new Blob(['\uFEFF'+content],{type:format==='csv'?'text/csv;charset=utf-8':'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=file.name.replace(/\.pdf$/i,'')+'.'+format;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}$('csv').onclick=()=>download('csv');$('txt').onclick=()=>download('txt');
